/// Runs with the given config, writing to stdout.
pub fn run_with(config: &cli::CliConfig) {
    for line in render(config) {
        println!("{line}");
    }
}

fn render(config: &cli::CliConfig) -> Vec<String> {
    let mut lines = vec![String::from("ulw-bench-fixture running")];
    if config.verbose {
        lines.push(format!("verbose: output={}", config.output));
    }
    lines
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn render_is_quiet_by_default() {
        let lines = render(&cli::CliConfig::new());
        assert_eq!(lines, vec!["ulw-bench-fixture running"]);
    }

    #[test]
    fn render_adds_detail_when_verbose() {
        let config = cli::CliConfig::from_args(["--verbose"]).unwrap();
        let lines = render(&config);
        assert_eq!(
            lines,
            vec!["ulw-bench-fixture running", "verbose: output=default"]
        );
    }
